effect.shader:

    vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
    mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
    vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);  vec3 hsv2rgb(vec3 c) { vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0); vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www); return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y); }  vec3 rgb2hsv(vec3 c) { vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0); vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g)); vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));  float d = q.x - min(q.w, q.y); float e = 1.0e-10; return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x); } highp mat3 rgb2yuv = mat3( 0.299,     0.587,    0.114, -0.14713,  -0.28886,  0.436, 0.615,    -0.51499, -0.10001 ); highp mat3 yuv2rgb = mat3( 1.0,  0.0,      1.13983, 1.0, -0.39465, -0.58060, 1.0,  2.03211,  0.0 );

    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 image_size = getTexSize(inputImg.size);
        vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
        vec2 iMouse = vec2(0.5, 0.5);

        /////////////////////////

    	vec4 fragColor;

             vec4 dst;
             vec4 inputColor;

             mat4 myMatrix;

             float fr = redValue*redValue*sign(redValue);
             float dr = -fr/2.0;

             float fg = greenValue*greenValue*sign(greenValue);
             float dg = -fg/2.0;

             float fb = blueValue*blueValue*sign(blueValue);
             float db = -fb/2.0;


             myMatrix[0][0] = 1.0 + fr;
             myMatrix[0][1] = dg;
             myMatrix[0][2] = db;
             myMatrix[0][3] = 0.0;

             myMatrix[1][0] = dr;
             myMatrix[1][1] = 1.0 + fg;
             myMatrix[1][2] = db;
             myMatrix[1][3] = 0.0;

             myMatrix[2][0] = dr;
             myMatrix[2][1] = dg;
             myMatrix[2][2] = 1.0 + fb;
             myMatrix[2][3] = 0.0;

             myMatrix[3][0] = 0.0;
             myMatrix[3][1] = 0.0;
             myMatrix[3][2] = 0.0;
             myMatrix[3][3] = 1.0;

             inputColor = texture2DCv(inputImg.texture, acScreenNorm.st);

             inputColor = inputColor * myMatrix;

             dst.rgb = min(inputColor.rgb,inputColor.a);
             dst.a = inputColor.a;

	fragColor = dst;

    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal; if( blendMode==0 ) { resultfinal = (factor * bright) * texColor.a; } else if( blendMode==1 ) {  factor *= bright; vec4 c = factor + vec4(1.)*(1.-factor.a); resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; } else if( blendMode==2 ) {  factor *= bright; resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; } else if(blendMode==3 ) { factor *= bright; vec3 t = smoothstep(0.5,0.5,texColor.rgb); vec3 result = t * (1. - (1.-2.*(texColor.rgb-0.5)) * (1.-factor.rgb)) + (1.-t) * ((2.*texColor.rgb) * factor.rgb); resultfinal = vec4(result, texColor.a) * texColor.a; } else if(blendMode==4 ) { vec3 colorBlend = vec3( (texColor.rgb * rgb2yuv).r, (factor.rgb * rgb2yuv).gb) * yuv2rgb; resultfinal = vec4(colorBlend,texColor.a) * texColor.a; } else if(blendMode==5 ) { factor *=bright; resultfinal = max(factor,texColor) * texColor.a; } else if(blendMode==6 ) { factor *=bright; resultfinal = texColor / (1.0-factor) * texColor.a; } else if(blendMode==7 ) { factor *=bright; resultfinal = (1. - (1.-texColor) / factor) * texColor.a; } else if(blendMode==8 ) { factor *=bright; resultfinal = (texColor + factor) * texColor.a; } else if(blendMode==9 ) { factor *=bright; resultfinal = (texColor + factor - 1.0) * texColor.a; } else if(blendMode==10 ) { vec3 t = smoothstep(0.5,0.5,factor.rgb); vec3 linearLight = t * (texColor.rgb + 2.*(factor.rgb-0.5)) + (1.-t) * (texColor.rgb + 2.*factor.rgb - 1.); resultfinal = vec4(linearLight,texColor.a) * texColor.a; } else if(blendMode==11 ) { factor *=bright; resultfinal = min(factor,texColor) * texColor.a; } else if(blendMode==12 ) { factor *=bright; vec3 darkenColor = length(luminanceWeighting * factor.rgb) > length(luminanceWeighting * texColor.rgb) ? texColor.rgb : factor.rgb; resultfinal = vec4(darkenColor,texColor.a) * texColor.a; } else if(blendMode==13 ) { factor *=bright; vec3 lightenColor = length(luminanceWeighting * factor.rgb) > length(luminanceWeighting * texColor.rgb) ? factor.rgb : texColor.rgb; resultfinal = vec4(lightenColor,texColor.a) * texColor.a; } else if(blendMode==14 ) { factor *=bright; vec3 t = smoothstep(0.5,0.5,factor.rgb); vec3 softLight = t * (1. - (1.-texColor.rgb) * (1.-(factor.rgb-0.5))) + (1.-t) * (texColor.rgb * (factor.rgb+0.5)); resultfinal = vec4(softLight,texColor.a) * texColor.a; } else if(blendMode==15 ) { factor *=bright; vec3 t = smoothstep(0.5,0.5,texColor.rgb); vec3 softOver = t * (1. - (1.-texColor.rgb) * (1.-(factor.rgb-0.5))) + (1.-t) * (texColor.rgb * (factor.rgb+0.5)); resultfinal = vec4(softOver,texColor.a) * texColor.a; } else if(blendMode==16 ) { factor *=bright; vec3 t = smoothstep(0.5,0.5,factor.rgb); vec3 hardLight = t * (1. - (1.-texColor.rgb) * (1.-2.*(factor.rgb-0.5))) + (1.-t) * (texColor.rgb * (2.*factor.rgb)); resultfinal = vec4(hardLight,texColor.a) * texColor.a; } else if(blendMode==17 ) { factor *=bright; vec3 hueB = hsv2rgb(vec3(rgb2hsv(factor.rgb).r, rgb2hsv(texColor.rgb).gb)); resultfinal = vec4(hueB,texColor.a) * texColor.a; } else if(blendMode==18 ) { factor *=bright; resultfinal = vec4(abs(texColor.rgb*texColor.a - factor.rgb),texColor.a); } else if(blendMode==19 ) { factor *=bright; vec3 lumin = vec3( (factor.rgb * rgb2yuv).r, (texColor.rgb * rgb2yuv).gb) * yuv2rgb; resultfinal = vec4(lumin,texColor.a) * texColor.a; } else if(blendMode==20 ) { factor *=bright; vec3 bot_hsv = rgb2hsv(texColor.rgb); vec3 satBlend = hsv2rgb(vec3(bot_hsv.r, rgb2hsv(factor.rgb).g, bot_hsv.b)); resultfinal = vec4(satBlend,texColor.a) * texColor.a; } else if(blendMode==21 ) { factor *=bright; vec3 t = smoothstep(0.5,0.5,factor.rgb); vec3 vividLight = t * (1. - (1.-texColor.rgb) * (2.*(factor.rgb-0.5))) + (1.-t) * (texColor.rgb * (1.-2.*factor.rgb)); resultfinal = vec4(vividLight,texColor.a) * texColor.a; } else if(blendMode==22 ) { factor *=bright; vec3 t = smoothstep(0.5,0.5,factor.rgb); vec3 pinLight = t * (max(texColor.rgb,2.*(factor.rgb-0.5))) + (1.-t) * (min(texColor.rgb,2.*factor.rgb)); resultfinal = vec4(pinLight,texColor.a) * texColor.a; } else if(blendMode==23 ) { factor *=bright; resultfinal = (texColor / factor) * texColor.a; } else if(blendMode==24 ) { factor *=bright; resultfinal = (texColor - factor) * texColor.a; } else if( blendMode==25 ) {  factor *= bright; resultfinal = newLayer(texColor, factor) * texColor.a; } 
    	vec4 satriyhaidfx = mix(factor,resultfinal, alphab);

    	gl_FragColor = mix(texColor, satriyhaidfx, alpha) * texColor.a;

    }
